//! Card 5.M2a acceptance: three ASS documents generated by real
//! ffmpeg (`ffmpeg -i <srt> -c:s ass out.ass`, ffmpeg 7.1.5-0+deb13u1)
//! parse to the exact expected cue counts, times (centisecond
//! tokens → the model's µs, ×10 000 exact) and plain texts.
//!
//! The fixtures are COMMITTED (`tests/fixtures/ass/`) so the AC is
//! deterministic and does not depend on a toolchain at test time;
//! the generation commands are recorded in the worklog and can be
//! replayed: the three SRT sources each had different content
//! (basic multi-line, unicode + literal `{\b1}` tags that survive
//! SRT→ASS conversion, and a six-cue even-spaced ladder).

use subtitles::ass;
use subtitles::model::cue::CueText;
use subtitles::model::position::{HorizontalAlign, VerticalAlign};
use subtitles::model::style::Color;

const BASIC: &str = include_str!("fixtures/ass/ac_basic.ass");
const UNICODE: &str = include_str!("fixtures/ass/ac_unicode.ass");
const SIX: &str = include_str!("fixtures/ass/ac_sixcues.ass");

/// Every ffmpeg header carries these; one fixture is checked in
/// full, the others spot-checked.
#[test]
fn ffmpeg_header_and_style_parse_clean() -> Result<(), Box<dyn std::error::Error>> {
    let doc = ass::parse(BASIC);
    assert_eq!(doc.info("ScriptType"), Some("v4.00+"));
    assert_eq!(doc.info("PlayResX"), Some("384"));
    assert_eq!(doc.info("PlayResY"), Some("288"));
    let style = doc.style("Default").ok_or("Default style defined")?;
    assert_eq!(style.font_name, "Arial");
    assert_eq!(style.font_size_milli, 16_000);
    // `&Hffffff` (BGR, no alpha byte) → opaque white.
    assert_eq!(style.primary_colour, Some(Color::WHITE));
    assert_eq!(style.margin_l, 10);
    assert_eq!(style.margin_r, 10);
    assert_eq!(style.margin_v, 10);
    // Alignment 2 (numpad) → bottom-center.
    assert_eq!(style.alignment.vertical, VerticalAlign::Bottom);
    assert_eq!(style.alignment.horizontal, HorizontalAlign::Center);
    assert!(doc.damage.is_empty(), "{:?}", doc.damage);
    assert!(doc.stats.dropped_tags.is_empty());
    Ok(())
}

#[test]
fn ffmpeg_basic_three_cues_times_and_text() -> Result<(), Box<dyn std::error::Error>> {
    let doc = ass::parse(BASIC);
    assert_eq!(doc.cues.len(), 3);
    let expected = [
        (1_000_000, 3_500_000, "Hello Lumen"),
        (4_250_000, 6_000_000, "Second line here\nwith two lines"),
        (10_000_000, 62_750_000, "Late and long"),
    ];
    for (i, (start, end, text)) in expected.iter().enumerate() {
        let cue = &doc.cues[i];
        assert_eq!(cue.id.get(), i as u64 + 1, "dense sequential ids");
        assert_eq!(cue.interval.start_us(), *start, "cue {i} start");
        assert_eq!(cue.interval.end_us(), *end, "cue {i} end");
        assert_eq!(cue.text, CueText::Plain((*text).to_owned()), "cue {i} text");
        // Style alignment respected, no explicit placement in v1.
        assert_eq!(
            cue.positioning.alignment,
            doc.style("Default").map(|s| s.alignment).ok_or("style")?
        );
    }
    // The multi-line SRT cue became an ASS `\N` → one hard newline.
    assert_eq!(doc.stats.hard_newlines, 1);
    assert!(doc.damage.is_empty(), "{:?}", doc.damage);
    Ok(())
}

#[test]
fn ffmpeg_unicode_and_tag_stripping() {
    let doc = ass::parse(UNICODE);
    assert_eq!(doc.cues.len(), 4);
    let expected: [(i64, i64, &str); 4] = [
        (500_000, 2_000_000, "Ünïcödé — 日本語テスト"),
        (3_100_000, 4_900_000, "Bold html & ampersand"),
        (5_000_000, 5_100_000, "Tick"),
        (600_000_000, 603_200_000, "Far future"),
    ];
    for (i, (start, end, _)) in expected.iter().enumerate() {
        assert_eq!(doc.cues[i].interval.start_us(), *start, "cue {i} start");
        assert_eq!(doc.cues[i].interval.end_us(), *end, "cue {i} end");
        // Plain payload for the tag-free cues.
        if i != 1 {
            assert_eq!(
                doc.cues[i].text,
                CueText::Plain(expected[i].2.to_owned()),
                "cue {i} text"
            );
        }
    }
    // ffmpeg passed the SRT's literal `Bold {\b1}html{\b0} &
    // ampersand` through; the G-2 override-tag engine (issue #17)
    // styles just the `html` run now: plain / bold / plain.
    assert!(matches!(&doc.cues[1].text, CueText::Styled(segs)
        if segs.len() == 3
            && segs[0].text == "Bold " && !segs[0].style.bold
            && segs[1].text == "html" && segs[1].style.bold
            && segs[2].text == " & ampersand" && !segs[2].style.bold));
    assert_eq!(doc.stats.stripped_override_blocks, 2);
    assert_eq!(doc.stats.applied_override_tags, 2);
    assert_eq!(doc.stats.dropped_tags.get("b"), None);
    assert!(doc.damage.is_empty(), "{:?}", doc.damage);
}

#[test]
fn ffmpeg_six_cue_ladder() -> Result<(), Box<dyn std::error::Error>> {
    let doc = ass::parse(SIX);
    assert_eq!(doc.cues.len(), 6);
    for (i, cue) in doc.cues.iter().enumerate() {
        let start = (2 + i as i64 * 2) * 1_000_000;
        let end = start + 2_000_000;
        assert_eq!(cue.interval.start_us(), start, "cue {i} start");
        assert_eq!(cue.interval.end_us(), end, "cue {i} end");
        let text = match &cue.text {
            CueText::Plain(t) => t.clone(),
            CueText::Styled(_) => return Err("styled payload in the plain subset".into()),
        };
        assert_eq!(text, (char::from(b'A' + i as u8)).to_string());
    }
    assert!(doc.damage.is_empty(), "{:?}", doc.damage);
    Ok(())
}
